<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantConfig\Domain\ValueObject\Accessor\TenantConfigRefreshTokenMaxLifetimeSecondsAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantConfigRefreshTokenMaxLifetimeSecondsAccessor trait.
 *
 * Covers null default, string/VO assignment via withRefreshTokenMaxLifetimeSeconds,
 * getRefreshTokenMaxLifetimeSeconds/refreshTokenMaxLifetimeSeconds accessors, and isRefreshTokenMaxLifetimeSecondsChanged with/without original.
 */
class TenantConfigRefreshTokenMaxLifetimeSecondsAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withRefreshTokenMaxLifetimeSeconds creates a new instance with the RefreshTokenMaxLifetimeSeconds set
     * from a string value, and getRefreshTokenMaxLifetimeSeconds returns the primitive string.
     */
    public function testWithRefreshTokenMaxLifetimeSecondsFromString(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigRefreshTokenMaxLifetimeSecondsAccessorUnitTest();

        // Act
        $result = $holder->withRefreshTokenMaxLifetimeSeconds(1);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(1, $result->getRefreshTokenMaxLifetimeSeconds());
    }
    /**
     * Asserts that withrefreshTokenMaxLifetimeSeconds has access to the value object
     * from a string value, and getRefreshTokenMaxLifetimeSeconds returns the primitive string.
     */
    public function testWithRefreshTokenMaxLifetimeSecondsFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigRefreshTokenMaxLifetimeSecondsAccessorUnitTest();

        // Act
        $result = $holder->withRefreshTokenMaxLifetimeSeconds(1);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(1, $result->refreshTokenMaxLifetimeSeconds()->value());
    }
    public function testChangedRefreshTokenMaxLifetimeSeconds(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigRefreshTokenMaxLifetimeSecondsAccessorUnitTest()->withRefreshTokenMaxLifetimeSeconds(1);
        $original = $holder->withRefreshTokenMaxLifetimeSeconds(1);
        $same = $holder->withRefreshTokenMaxLifetimeSeconds(1);
        $modified = $holder->withRefreshTokenMaxLifetimeSeconds(2);

        // Act
        $withSame = $original->isRefreshTokenMaxLifetimeSecondsChanged($same);
        $withDiferent = $original->isRefreshTokenMaxLifetimeSecondsChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTenantConfigRefreshTokenMaxLifetimeSecondsAccessorUnitTest
{
    use TenantConfigRefreshTokenMaxLifetimeSecondsAccessor;
}
